# -*- coding: utf-8 -*-
# Задачи с одним неверным вариантом (показывались как ввод ответа): по решению владельца 26.09 добавлены варианты с описанием ошибки.
# Каждый ключ пересчитан заново; каждый новый вариант проверен (check_v5d.py): не равен ключу и другим вариантам.
P = {}
W = "у задачи был один неверный вариант (показывалась как задача с вводом ответа); по решению владельца добавлены неверные варианты с описанием типичной ошибки; ключ пересчитан: "
def E(t, why, add, dval=None):
    P[t] = {"why": W + why, "src": "решение владельца 26.09 + самостоятельный пересчёт", "dadd": add}
    if dval: P[t]["dval"] = dval
E("G7_ALG_22_7.1", "a⁹/a¹³ = 1/a⁴", [(r"$\dfrac{1}{a^{22}}$", "Ученик сложил показатели степеней (9 + 13) вместо того, чтобы вычесть их при делении."),
   (r"$\dfrac{9}{13}$", "Ученик «сократил» букву a и оставил показатели степеней как обычные числа.")], {0: r"$a^{4}$"})
E("G10_TB_§10_10_1_4", "(m + n)^{2,5} = (m + n)^{5/2} = √((m + n)⁵)", [(r"$\sqrt[5]{(m+n)^{2}}$", "Ученик перепутал числитель и знаменатель дробного показателя 5/2: показатель корня — знаменатель, а не числитель."),
   (r"$\sqrt{m^{5}+n^{5}}$", "Ученик возвёл в степень каждое слагаемое отдельно, хотя степень суммы так не раскрывается.")], {0: r"$\sqrt{(m+n)^{2{,}5}}$"})
E("G10_TB_3_18_a", "2cos²(α/2) = 1 + cos α, (1 + cos α)(cos α − 1) = cos²α − 1 = −sin²α", [(r"$-\cos^{2}\alpha$", "Ученик перепутал основное тригонометрическое тождество: принял cos²α − 1 за −cos²α вместо −sin²α."),
   (r"$\cos^{2}\alpha - \cos\alpha$", "Ученик заменил 2cos²(α/2) на cos α, потеряв единицу в формуле понижения степени 2cos²(α/2) = 1 + cos α.")])
E("G11_TB_16_2*_16_18_1", "(3 + 2i)(1 − 5i)/26 = (13 − 13i)/26 = 1/2 − i/2", [(r"$3 + \dfrac{2}{5}i$", "Ученик разделил действительную часть на действительную, а мнимую — на мнимую, что неверно для комплексных чисел."),
   (r"$-\dfrac{13}{24} + \dfrac{13}{24}i$", "Ученик в знаменателе вычислил (1 + 5i)(1 − 5i) как 1 − 25, забыв, что i² = −1 (должно быть 1 + 25 = 26).")])
